{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "The closest analogue by Morgan similarity (0.35), a 3-methylphenyl urea, has a measured human oral bioavailability of 0.7857, directly supporting high F for the query's related aryl-urea/sulfonylurea scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Tolbutamide, a classic sulfonylurea sharing the same sulfonylurea core as the query, has absolute human oral bioavailability of 80–90%, providing strong functional-class evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Recainam, a substituted aryl urea with an isopropylamine side chain, shows 73% absolute oral bioavailability in healthy men, supporting high F for the query's urea/isopropyl motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Lumiracoxib has an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects, adding consistent human evidence that structurally related aniline/aryl compounds achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Pimasertib, a pyridine-aniline analogue, has an absolute oral bioavailability of 73% (90% CI 61–87%) in patients, directly supporting high F for the query's pyridine-aniline core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lisofylline is reported with only 5.9% oral bioavailability, but it is structurally distant and lacks the sulfonylurea/aryl-urea features of the query, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple human absolute bioavailability measurements in structurally related aryl ureas, sulfonylureas, and pyridine-anilines are consistently high (64–90%), outweighing the single low-bioavailability analogue and the uncertain physicochemical prior. The query's sulfonylurea and aryl-urea features align most strongly with tolbutamide and related high-F compounds, supporting a high F ≥ 20% prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "Morgan similarities to the evidence molecules are modest (0.23–0.35), limiting quantitative transferability.",
    "The lisofylline low-bioavailability record appears structurally inconsistent with its listed SMILES, reducing its weight.",
    "Potential transporter-mediated efflux or first-pass metabolism for this exact scaffold is not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

